 static class LaunchProfiles {
  const string ModId="OrangeLauncherSession";const string RequestName="OrangeLauncherSession.request";const string StatusName="OrangeLauncherSession.status";
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=2097152};
  public static string Key(Engine e){return DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(e.Game).ToUpperInvariant()+"|"+Path.GetFullPath(e.User).ToUpperInvariant()));}
  static string Journal(Engine e){return Path.Combine(e.Data,"launch-sessions",Key(e)+".json");}
  static string MutexName(Engine e){return "Local\\OrangeLaunch-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(e.User).ToUpperInvariant()));}
  public static string Recover(Engine e,bool force=false,string expectedNonce=null){using(var mutex=new Mutex(false,MutexName(e))){bool acquired=false;try{try{acquired=mutex.WaitOne(0);}catch(AbandonedMutexException){acquired=true;}if(!acquired)return "另一个启动任务正在准备，请稍后恢复。";if(PlayProfileTransaction.Pending(e))return PlayProfileTransaction.PendingMessage;if(!Pending(e))return "";if(expectedNonce!=null&&Load(e).Nonce!=expectedNonce)return "旧会话已结束；未改动新会话。";return RecoverUnlocked(e,force);}finally{if(acquired)mutex.ReleaseMutex();}}}
  public static bool Pending(Engine e){return File.Exists(Journal(e));}
  public static void ExpireRequest(Engine e,string expectedNonce){using(var mutex=new Mutex(false,MutexName(e))){bool acquired=false;try{try{acquired=mutex.WaitOne(0);}catch(AbandonedMutexException){acquired=true;}if(!acquired||!Pending(e))return;var record=Load(e);DateTime created;if(record.Nonce!=expectedNonce||!DateTime.TryParse(record.CreatedUtc,out created)||DateTime.UtcNow-created.ToUniversalTime()<TimeSpan.FromSeconds(120))return;string request=Path.Combine(e.User,RequestName);LauncherMaintenance.NoReparse(request);if(File.Exists(request)&&new FileInfo(request).Length>0){ClearRequest(e);Atomic(Path.Combine(e.User,StatusName),Encoding.UTF8.GetBytes("expired-or-invalid-request\n"));}}finally{if(acquired)mutex.ReleaseMutex();}}}
  static bool Alive(Process process){if(process==null)return false;try{return !process.HasExited;}catch{return false;}}
  static string Clean(string s,int maximum=256){s=s??"";if(s.Length>maximum||s.Any(c=>c<' '||c=='\u007f'))throw new Exception("启动配置包含无效长度或控制字符。");return s;}
  public static string BuildDefault(string original,string kind,string[] retained){
   if(kind!="save"&&kind!="server")throw new Exception("未知启动类型。");var mods=Regex.Matches(original,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,").Cast<Match>().Select(m=>m.Groups[1].Value.Trim()).ToList();
   var keep=kind=="server"?mods.Where(id=>retained.Contains(id)).ToList():mods;keep.RemoveAll(x=>x==ModId);keep.Insert(0,ModId);
   var block=Regex.Match(original,@"\bmods\s*\{(?<body>[^}]*)\}");if(!block.Success||Regex.Matches(original,@"\bmods\s*\{").Count!=1)throw new Exception("无法安全识别本地模组清单。");
   string body="\r\n"+string.Join("",keep.Distinct().Select(id=>"    mod = "+id+",\r\n"));string result=original.Substring(0,block.Groups["body"].Index)+body+original.Substring(block.Groups["body"].Index+block.Groups["body"].Length);
   if(kind=="server"){var maps=Regex.Match(result,@"\bmaps\s*\{(?<body>[^}]*)\}");if(!maps.Success)throw new Exception("本地地图清单无法识别。");result=result.Substring(0,maps.Groups["body"].Index)+"\r\n"+result.Substring(maps.Groups["body"].Index+maps.Groups["body"].Length);}
   return result;
  }
  internal static string[] Retained(Engine e){return Retained(e,null);}
  internal static string[] Retained(Engine e,LaunchReadBudget budget){if(!ShootClient.BaseReady(e))return new string[0];var list=new List<string>{"ZombieBuddy","Viewpoint"};if(e.HasModels)list.Add("PZVoxelStudioViewpoint");if(ShootClient.Enabled(e))list.Add(ShootClient.Id);if(ChinesePatch.Enabled(e))list.Add(ChinesePatch.Id);if(new PresentationBridge().Enabled(e))list.Add(PresentationBridge.Id);foreach(var addon in ViewpointAddons.All.Where(a=>ViewpointAddons.Enabled(e,a))){try{if(ViewpointAddons.Preload(ViewpointAddons.Find(e,addon,budget),budget))list.Add(addon.Id);}catch{if(budget!=null)budget.Unknown();}}return list.ToArray();}
  static void Atomic(string path,byte[] bytes){LauncherMaintenance.NoReparse(path);Directory.CreateDirectory(Path.GetDirectoryName(path));string temporary=path+".orange-"+Guid.NewGuid().ToString("N");try{File.WriteAllBytes(temporary,bytes);if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
  static byte[] Script(){return BundledAssets.ReadOwnAsset("OrangeLaunchBridge.lua");}
  static void PrivateRequest(string path,string text){LauncherMaintenance.NoReparse(path);if(File.Exists(path))throw new Exception("存在尚未清理的启动请求，拒绝覆盖。");var security=new FileSecurity();security.SetAccessRuleProtection(true,false);security.AddAccessRule(new FileSystemAccessRule(WindowsIdentity.GetCurrent().User,FileSystemRights.FullControl,AccessControlType.Allow));using(var file=new FileStream(path,FileMode.CreateNew,FileSystemRights.Write,FileShare.None,4096,FileOptions.None,security)){byte[] bytes=new UTF8Encoding(false).GetBytes(text);file.Write(bytes,0,bytes.Length);}}
  static string Payload(ProfileLaunchRequest r){Clean(r.Kind);Clean(r.Id);if(r.Kind=="save"){if(string.IsNullOrWhiteSpace(r.Mode)||string.IsNullOrWhiteSpace(r.Save)||new[]{r.Mode,r.Save}.Any(s=>s=="."||s==".."||s.IndexOfAny(new[]{'\\','/',':'})>=0)||r.Mode=="Multiplayer")throw new Exception("存档标识无效。");}else if(r.Kind=="server"){if(string.IsNullOrWhiteSpace(r.Host)||r.Port<1||r.Port>65535||string.IsNullOrWhiteSpace(r.Username))throw new Exception("服务器连接配置不完整。");}else throw new Exception("未知启动目标。");
   return string.Join("\n",new[]{"ORANGE1",Guid.NewGuid().ToString("N"),DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString(),r.Kind,Clean(r.Mode),Clean(r.Save),Clean(r.Host),r.Port.ToString(),Clean(r.Username),Clean(r.UserPassword,1024),Clean(r.ServerPassword,1024),r.UseSteamRelay?"1":"0"})+"\n";
  }
  public static void Stage(Engine e,ProfileLaunchRequest r){
   e.Guard();foreach(string path in new[]{e.User,e.Mods,e.Data,Journal(e)})LauncherMaintenance.NoReparse(path);if(Pending(e))throw new Exception("上一次启动配置尚未恢复，请查看启动状态。");string payload=Payload(r);
   byte[] original=File.Exists(e.Mods)?File.ReadAllBytes(e.Mods):null;if(original!=null&&original.Length>1048576)throw new Exception("模组清单异常过大。");string text=original==null?"VERSION = 1,\r\nmods\r\n{\r\n}\r\nmaps\r\n{\r\n}\r\n":new UTF8Encoding(false,true).GetString(original).TrimStart('\uFEFF');string next=BuildDefault(text,r.Kind,Retained(e));byte[] applied=new UTF8Encoding(original!=null&&original.Length>=3&&original[0]==239&&original[1]==187&&original[2]==191).GetPreamble().Concat(new UTF8Encoding(false).GetBytes(next)).ToArray();
   string folder=Path.Combine(e.User,"mods",ModId);LauncherMaintenance.NoReparse(folder);if(Directory.Exists(folder))throw new Exception("发现已有同名启动桥接目录，未覆盖。");string request=Path.Combine(e.User,RequestName),status=Path.Combine(e.User,StatusName);LauncherMaintenance.NoReparse(request);LauncherMaintenance.NoReparse(status);if(File.Exists(request))throw new Exception("存在上次启动请求，未覆盖。");
   var record=new ProfileSessionRecord{Game=e.Game,User=e.User,Original=original==null?null:Convert.ToBase64String(original),AppliedHash=DlssInstaller.Hash(applied),CreatedUtc=DateTime.UtcNow.ToString("o"),State="prepared",Token=Key(e),Nonce=Guid.NewGuid().ToString("N")};
   var files=new Dictionary<string,byte[]>{{Path.Combine(folder,"common","mod.info"),Encoding.UTF8.GetBytes("name=Orange Launcher Session\nid="+ModId+"\ndescription=一次性客户端启动桥接，不修改服务器。\n")},{Path.Combine(folder,"42","mod.info"),Encoding.UTF8.GetBytes("name=Orange Launcher Session\nid="+ModId+"\n")},{Path.Combine(folder,"42","media","lua","client","OrangeLaunchBridge.lua"),Script()}};
   foreach(var file in files)record.Files[file.Key]=DlssInstaller.Hash(file.Value);
   Atomic(Journal(e),Encoding.UTF8.GetBytes(Json.Serialize(record)));
   try{foreach(var file in files)Atomic(file.Key,file.Value);PrivateRequest(request,payload);Atomic(status,Encoding.UTF8.GetBytes("prepared\n"));if(!SameOriginal(e.Mods,original))throw new Exception("准备期间本地模组清单改变，拒绝覆盖。");if(!e.TestMode&&GameProcessGuard.IsRunning(e.Game))throw new Exception("游戏已启动，取消配置切换。");Atomic(e.Mods,applied);}catch{Recover(e,true);throw;}
  }
  static bool SameOriginal(string file,byte[] original){return original==null?!File.Exists(file):File.Exists(file)&&File.ReadAllBytes(file).SequenceEqual(original);}
  static void ValidateRecord(Engine e,ProfileSessionRecord record){if(record.Files==null||record.Files.Count!=3||!Regex.IsMatch(record.Nonce??"",@"^[a-f0-9]{32}$")||!Regex.IsMatch(record.AppliedHash??"",@"^[A-F0-9]{64}$"))throw new Exception("启动恢复记录缺少有效会话及文件校验。");string folder=Path.Combine(e.User,"mods",ModId);var allowed=new HashSet<string>(new[]{Path.Combine(folder,"common","mod.info"),Path.Combine(folder,"42","mod.info"),Path.Combine(folder,"42","media","lua","client","OrangeLaunchBridge.lua")},StringComparer.OrdinalIgnoreCase);foreach(var file in record.Files){if(!allowed.Contains(Path.GetFullPath(file.Key))||!Regex.IsMatch(file.Value??"",@"^[A-F0-9]{64}$"))throw new Exception("启动恢复记录文件越界或校验无效。");LauncherMaintenance.NoReparse(file.Key);}if(record.Original!=null&&Convert.FromBase64String(record.Original).Length>1048576)throw new Exception("启动恢复原文件异常过大。");}
  static ProfileSessionRecord Load(Engine e){LauncherMaintenance.NoReparse(Journal(e));if(new FileInfo(Journal(e)).Length>2097152)throw new Exception("启动恢复记录异常过大。");var r=Json.Deserialize<ProfileSessionRecord>(File.ReadAllText(Journal(e)));if(r==null||!string.Equals(Path.GetFullPath(r.Game),Path.GetFullPath(e.Game),StringComparison.OrdinalIgnoreCase)||!string.Equals(Path.GetFullPath(r.User),Path.GetFullPath(e.User),StringComparison.OrdinalIgnoreCase)||r.Token!=Key(e))throw new Exception("启动恢复记录与游戏目录不一致。");ValidateRecord(e,r);return r;}
  static void ClearRequest(Engine e){string file=Path.Combine(e.User,RequestName);LauncherMaintenance.NoReparse(file);if(File.Exists(file)){Atomic(file,new byte[0]);File.Delete(file);}}
  static string StageText(string value){if(value=="prepared")return "正在准备一次性启动目标。";if(value=="submitted-save")return "读档请求已交给游戏；授权、版本转换等提示仍由游戏处理。";if(value=="submitted-server")return "连接请求已交给游戏；是否成功进入服务器以游戏为准。";if(value.StartsWith("failed")||value.StartsWith("invalid")||value.StartsWith("expired"))return "自动直达未完成，请在游戏原入口继续；退出后恢复本地清单。";return value==""?"":"启动状态需检查。";}
  static string RecoverUnlocked(Engine e,bool force=false){if(!Pending(e))return "";if(!e.TestMode&&GameProcessGuard.IsRunning(e.Game))return "游戏仍在运行；临时模组配置将在退出后恢复。";var r=Load(e);DateTime created;if(!force&&r.State=="prepared"&&DateTime.TryParse(r.CreatedUtc,out created)&&DateTime.UtcNow-created.ToUniversalTime()<TimeSpan.FromSeconds(90))return "启动请求准备中，暂不覆盖临时配置。";
   LauncherMaintenance.NoReparse(e.Mods);byte[] original=r.Original==null?null:Convert.FromBase64String(r.Original);bool applied=File.Exists(e.Mods)&&DlssInstaller.HashFile(e.Mods)==r.AppliedHash;if(!applied&&!SameOriginal(e.Mods,original)){ClearRequest(e);return "本地模组清单被外部修改，未覆盖；启动恢复记录已保留，请人工核对。";}
   if(applied){if(original==null)File.Delete(e.Mods);else Atomic(e.Mods,original);}ClearRequest(e);string folder=Path.Combine(e.User,"mods",ModId);foreach(var file in r.Files){if(!Path.GetFullPath(file.Key).StartsWith(Path.GetFullPath(folder)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("恢复记录文件越界。");LauncherMaintenance.NoReparse(file.Key);if(File.Exists(file.Key)&&DlssInstaller.HashFile(file.Key)==file.Value)File.Delete(file.Key);}
   foreach(string directory in new[]{Path.Combine(folder,"42","media","lua","client"),Path.Combine(folder,"42","media","lua"),Path.Combine(folder,"42","media"),Path.Combine(folder,"42"),Path.Combine(folder,"common"),folder}){LauncherMaintenance.NoReparse(directory);if(Directory.Exists(directory)&&!Directory.EnumerateFileSystemEntries(directory).Any())Directory.Delete(directory);}
   File.Delete(Journal(e));return "已恢复启动前的本地模组清单；未修改存档或服务器配置。";
  }
  public static object State(Engine e){string warning="";try{if(Pending(e))warning="存在尚未恢复的启动会话；退出游戏后可恢复原本地清单。";string status=Path.Combine(e.User,StatusName);LauncherMaintenance.NoReparse(status);string stage=File.Exists(status)&&new FileInfo(status).Length<=1024?File.ReadAllText(status).Trim():"";return new{pending=Pending(e),stage=StageText(stage),warning=warning};}catch(Exception ex){return new{pending=Pending(e),stage="恢复需检查",warning=ex.Message};}}
  public static object Launch(Engine e,ProfileLaunchRequest r){if(e.TestMode)throw new Exception("测试模式禁止真实游戏启动。");string reason=LauncherLaunch.Reason(e,false,GameProcessGuard.IsRunning(e.Game));if(reason!="")throw new Exception(reason);string mutexName=MutexName(e);using(var mutex=new Mutex(false,mutexName)){bool acquired=false;try{try{acquired=mutex.WaitOne(0);}catch(AbandonedMutexException){acquired=true;}if(!acquired)throw new Exception("另一个启动器正在准备游戏。");Recover(e);Stage(e,r);var start=new ProcessStartInfo(Path.Combine(e.Game,"ProjectZomboid64.exe")){UseShellExecute=false,WorkingDirectory=e.Game};Process game;try{game=Process.Start(start);}catch{Recover(e,true);throw;}var record=Load(e);record.Pid=game.Id;record.Birth=game.StartTime.ToUniversalTime().Ticks;record.State="launched";Atomic(Journal(e),Encoding.UTF8.GetBytes(Json.Serialize(record)));game.Dispose();try{Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--session-watch "+Key(e)+" "+record.Nonce){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=AppDomain.CurrentDomain.BaseDirectory}).Dispose();}catch{return new{message="游戏已启动，但退出监控未启动；请保留启动器，退出后刷新状态恢复配置。",stage="已请求启动，进服/读档尚待游戏确认"};}return new{message="已启动游戏并准备一次性目标；安全授权、版本转换或登录失败仍由游戏提示。",stage="已请求启动，进服/读档尚待游戏确认"};}finally{if(acquired)mutex.ReleaseMutex();}}}
  public static int Watch(string token,string nonce){try{if(!Regex.IsMatch(token??"",@"^[A-F0-9]{64}$")||!Regex.IsMatch(nonce??"",@"^[a-f0-9]{32}$"))return 1;string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PZ3DManager"),journal=Path.Combine(data,"launch-sessions",token+".json");LauncherMaintenance.NoReparse(journal);if(!File.Exists(journal))return 0;var r=Json.Deserialize<ProfileSessionRecord>(File.ReadAllText(journal));string user=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Zomboid");if(r.User!=user||r.Token!=token||r.Nonce!=nonce||!GameDiscovery.IsGameFolder(r.Game))return 1;var e=new Engine(r.Game,user,data);Load(e);Process original=null;try{original=Process.GetProcessById(r.Pid);if(original.StartTime.ToUniversalTime().Ticks!=r.Birth){original.Dispose();original=null;}}catch{}try{while(Alive(original)||GameProcessGuard.IsRunning(e.Game)){ExpireRequest(e,nonce);Thread.Sleep(2000);}}finally{if(original!=null)original.Dispose();}Thread.Sleep(2000);Recover(e,true,nonce);return 0;}catch{return 1;}}
